export type PaletteGroup = 'COLOR' | 'EFFECT';

export interface PaletteColor {
  code: string;
  /** The chart's name (brand colour names are not translated). */
  name: string;
  group: PaletteGroup;
  hex: string;
}

const color = (name: string, hex: string, group: PaletteGroup = 'COLOR'): PaletteColor => ({
  code: name.toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_|_$/g, ''),
  name,
  group,
  hex,
});

