export type CutCode = 'ROUND' | 'OVAL' | 'EMERALD' | 'CABOCHON' | 'CABOCHON_OVAL' | 'ROSE';

export interface CutDef {
  code: CutCode;
  labelHe: string;
  labelEn: string;
  /** A smooth (unfaceted) top. */
  cabochon: boolean;
}

