export function stoneDef(code: unknown): StoneDef | null {
  return typeof code === 'string' ? STONES.find((s) => s.code === code) ?? null : null;
}

/** The cuts a stone is made in: cabochons only for the stones the sheet says are never faceted. */
export function allowedCuts(stoneCode: unknown): CutCode[] {
  const def = stoneDef(stoneCode);
  return def?.cabochonOnly ? ['CABOCHON', 'CABOCHON_OVAL'] : CUTS.map((c) => c.code);
}

export function defaultCut(stoneCode: unknown): CutCode {
  return allowedCuts(stoneCode)[0];
}

/**
 * Weight per mm³ of a cut's girdle size (longest side), with the stone's specific gravity:
 * round brilliant 0.0061 × D² × depth (depth 61 %) scaled from diamond (SG 3.52); fancy cuts
 * and cabochons by their usual factors.
 */
const CUT_WEIGHT_FACTOR: Record<CutCode, number> = {
  ROUND: 0.0061 * 0.61 / 3.52,
  OVAL: 0.0062 * 0.72 * 0.432 / 3.52,
  EMERALD: 0.008 * 0.72 * 0.432 / 3.52,
  CABOCHON: 0.0026 * 0.45,
  CABOCHON_OVAL: 0.0026 * 0.45 * 0.72,
  ROSE: 0.0061 * 0.4 / 3.52,
};

/** Estimated carat weight of a stone of `sizeMm` (girdle diameter or longest side). */
export function caratEstimate(stoneCode: unknown, cut: CutCode, sizeMm: number): number {
  const sg = stoneDef(stoneCode)?.specificGravity ?? 3.52;
  return CUT_WEIGHT_FACTOR[cut] * sg * Math.pow(sizeMm, 3);
}

/** The sheet's range for a stone: "2 mm – 1.5 ct". */
export const STONE_MIN_MM = 2;
export const STONE_MAX_CARAT = 1.5;

/** The largest size (mm, one decimal, rounded down) at which the stone stays within 1.5 ct. */
export function stoneMaxMm(stoneCode: unknown, cut: CutCode): number {
  const sg = stoneDef(stoneCode)?.specificGravity ?? 3.52;
  const d = Math.cbrt(STONE_MAX_CARAT / (CUT_WEIGHT_FACTOR[cut] * sg));
  return Math.floor(d * 10) / 10;
}

