// ---------------------------------------------------------------------------------------------
// Pavé / band metal (pave_setting_parameters.xlsx)
// ---------------------------------------------------------------------------------------------

export interface PaveRow {
  /** Round stone diameter (mm). */
  stoneMm: number;
  /** "Minimum metal thickness" range (height), mm. */
  metalMinMm: number;
  metalMaxMm: number;
  /** "Recommended wall thickness per side", mm. */
  wallMm: number;
  /** "Recommended overall material width" of one row, mm. */
  widthMm: number;
}

export const PAVE_TABLE: readonly PaveRow[] = [
  { stoneMm: 1.0, metalMinMm: 1.25, metalMaxMm: 1.3, wallMm: 0.2, widthMm: 1.4 },
  { stoneMm: 1.25, metalMinMm: 1.45, metalMaxMm: 1.5, wallMm: 0.22, widthMm: 1.7 },
  { stoneMm: 1.5, metalMinMm: 1.65, metalMaxMm: 1.7, wallMm: 0.25, widthMm: 2.0 },
  { stoneMm: 1.75, metalMinMm: 1.85, metalMaxMm: 1.9, wallMm: 0.27, widthMm: 2.3 },
  { stoneMm: 2.0, metalMinMm: 2.1, metalMaxMm: 2.2, wallMm: 0.3, widthMm: 2.6 },
  { stoneMm: 2.5, metalMinMm: 2.6, metalMaxMm: 2.7, wallMm: 0.32, widthMm: 3.15 },
  { stoneMm: 3.0, metalMinMm: 3.1, metalMaxMm: 3.2, wallMm: 0.35, widthMm: 3.7 },
  { stoneMm: 3.5, metalMinMm: 3.6, metalMaxMm: 3.7, wallMm: 0.35, widthMm: 4.2 },
  { stoneMm: 4.0, metalMinMm: 4.1, metalMaxMm: 4.2, wallMm: 0.4, widthMm: 4.8 },
];

/** The band stone sizes the table covers (1–4 mm). */
export const BAND_STONE_SIZES_MM: readonly number[] = PAVE_TABLE.map((r) => r.stoneMm);

/** "Leave the channel width in the model about 0.05 mm wider than the final measurement." */
export const BRIGHT_CUT_ALLOWANCE_MM = 0.05;

function paveRow(stoneMm: number): { lo: PaveRow; hi: PaveRow; t: number } {
  const rows = PAVE_TABLE;
  if (stoneMm <= rows[0].stoneMm) return { lo: rows[0], hi: rows[0], t: 0 };
  for (let i = 1; i < rows.length; i++) {
    if (stoneMm <= rows[i].stoneMm) {
      const lo = rows[i - 1];
      const hi = rows[i];
      return { lo, hi, t: (stoneMm - lo.stoneMm) / (hi.stoneMm - lo.stoneMm) };
    }
  }
  const last = rows[rows.length - 1];
  return { lo: last, hi: last, t: 0 };
}

const mix = (a: number, b: number, t: number) => a + (b - a) * t;

/** Band metal height for stones of `stoneMm` (the table's upper value, interpolated). */
export function bandMetalThicknessMm(stoneMm: number): number {
  const { lo, hi, t } = paveRow(stoneMm);
  return Math.round(mix(lo.metalMaxMm, hi.metalMaxMm, t) * 100) / 100;
}

export function bandWallMm(stoneMm: number): number {
  const { lo, hi, t } = paveRow(stoneMm);
  return Math.round(mix(lo.wallMm, hi.wallMm, t) * 1000) / 1000;
}

/**
 * The band width `rows` rows of `stoneMm` stones need: the table's width for one row (stones
 * plus a wall on each side), each further row a stone and a wall more, plus the bright-cut
 * allowance.
 */
export function bandWidthForStonesMm(stoneMm: number, rows = 1): number {
  const { lo, hi, t } = paveRow(stoneMm);
  const one = mix(lo.widthMm, hi.widthMm, t);
  const more = Math.max(0, rows - 1) * (stoneMm + bandWallMm(stoneMm));
  return Math.round((one + more + BRIGHT_CUT_ALLOWANCE_MM) * 100) / 100;
}

