/** Older designs' element codes. */
export const LEGACY_ELEMENTS: Record<string, string> = { INITIAL: 'LETTERS' };

export function elementDef(code: unknown): ElementDef | null {
  if (typeof code !== 'string') return null;
  const c = LEGACY_ELEMENTS[code] ?? code;
  return ELEMENTS.find((e) => e.code === c) ?? null;
}

/** Letters and digits an element can carry: the Latin and Hebrew alphabets (final forms too), 0–9. */
export const LATIN_LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
export const HEBREW_LETTERS = 'אבגדהוזחטיכךלמםנןסעפףצץקרשת';
export const DIGITS = '0123456789';
/** The most characters one letters / numbers element carries (a name, a date). */
export const MAX_ELEMENT_TEXT = 8;

/** The element's text with what it cannot carry left out (upper-case Latin, Hebrew, digits). */
export function elementText(def: ElementDef | null, text: unknown): string {
  if (!def?.text || typeof text !== 'string') return '';
  const allowed = def.text === 'DIGITS' ? DIGITS : LATIN_LETTERS + HEBREW_LETTERS;
  return Array.from(text.toUpperCase())
    .filter((ch) => allowed.includes(ch))
    .slice(0, MAX_ELEMENT_TEXT)
    .join('');
}

// ---------------------------------------------------------------------------------------------
// Placement (where the user puts each stone and element)
// ---------------------------------------------------------------------------------------------

/** How far an item can be turned about its own centre, degrees either way. */
export const MAX_ROTATION_DEG = 180;

/** The ring band's top, where a centre stone's head stands unless the user moves it. */
export const RING_TOP_DEG = 90;
/** The bottom of a necklace / bracelet, where a pendant hangs unless the user moves it. */
export const CHAIN_BOTTOM_DEG = 270;

/** How far from the centre an earring's further stones and elements can go (mm; 0 = beside it). */
export const EARRING_ORBIT_MAX_MM = 15;

/** How the user can move an item: along the piece, across it, and turn it. */
export interface PlacementControls {
  /** Along the piece: around the ring band, along the chain, or around the earring's centre. */
  angle: boolean;
  /** Across the ring band (along the finger), or the distance from the earring's centre. */
  across: 'BAND' | 'DISTANCE' | null;
  rotation: boolean;
}

/**
 * The moves the geometry honours for the `index`th stone or element of a piece. A ring's centre
 * stone stands in its head on the band's middle line; an earring's centre (its first stone, or
 * its first element when it has no stone, and a drop's hanging element) stays where the earring is.
 */
export function placementControls(
  itemType: string,
  kind: 'STONE' | 'ELEMENT',
  index: number,
  piece: { stones: number; centreHead: boolean; earringStyle?: string },
): PlacementControls {
  const along = (across: PlacementControls['across']): PlacementControls => ({ angle: true, across, rotation: true });
  const fixed: PlacementControls = { angle: false, across: null, rotation: true };
  if (itemType === 'NECKLACE' || itemType === 'BRACELET') return along(null);
  if (itemType === 'EARRINGS') {
    const drop = (piece.earringStyle ?? '').toLowerCase() === 'drop';
    if (kind === 'STONE') return index === 0 ? fixed : along('DISTANCE');
    if (index === 0 && (drop || piece.stones === 0)) return fixed;
    return along('DISTANCE');
  }
  if (kind === 'STONE' && index === 0 && piece.centreHead) return along(null);
  return along('BAND');
}
